import { notFound } from "next/navigation";
import { getHostingAccount } from "@/lib/actions-hosting";
import { db } from "@/lib/db";
import { decryptSecret } from "@/lib/crypto-box";
import { hostingProvisioningStep } from "@/lib/provisioning-step";
import { StatusDot, Badge } from "@/components/ui/primitives";
import { AutoRefresh } from "@/components/AutoRefresh";
import { Provisioning } from "@/components/nx/Provisioning";
import { HostingTabs } from "@/components/customer/hosting/HostingTabs";

export const dynamic = "force-dynamic";

export default async function HostingAccountPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ tab?: string; path?: string; purchase?: string }>;
}) {
  const [{ id }, { tab, path, purchase }] = await Promise.all([params, searchParams]);

  // getHostingAccount enforces owner-or-admin (throws) and returns null if missing.
  let account: Awaited<ReturnType<typeof getHostingAccount>> = null;
  try {
    account = await getHostingAccount(id);
  } catch {
    notFound();
  }
  if (!account) notFound();

  const transitional = account.status === "PENDING" || account.status === "PROVISIONING";

  // Ownership/admin access was already established by getHostingAccount above —
  // this second, narrower lookup just pulls the extra raw fields the overlay
  // needs (the encrypted SFTP credential, the node's address) that the public
  // HostingAccountView doesn't carry. Real progress label: see
  // lib/provisioning-step.ts — while PENDING/PROVISIONING it's the worker's own
  // per-command-group label; once ACTIVE it's whichever content task (most
  // commonly a WordPress install queued at order time) is still running.
  const [raw, stepLabel] = await Promise.all([
    db.hostingAccount.findUnique({
      where: { id: account.id },
      select: { sftpPasswordEnc: true, node: { select: { publicIp: true, hostnameFqdn: true } } },
    }),
    hostingProvisioningStep(account.id),
  ]);
  const sftpPassword = raw?.sftpPasswordEnc ? decryptSecret(raw.sftpPasswordEnc) : null;
  const sftpHost = raw?.node?.hostnameFqdn || raw?.node?.publicIp || null;
  // True while a real follow-on step (e.g. that WordPress install) is still
  // running even though the account itself already flipped ACTIVE — see
  // ProvisioningOverlay's `liveStepActive` prop doc for why this is safe against
  // hijacking the screen for a later, casual install.
  const installStepActive = account.status === "ACTIVE" && stepLabel !== null;

  /* The Nexion provisioning screen, the SAME component the VPS flow uses, so a
     hosting customer sees the design rather than the old overlay card. Driven by
     the same real signals: the account's status and `hostingProvisioningStep`.
     `service="hosting"` picks the cloud mark and the resources panel; there is
     no game tier here, so no slots. */
  const overlay = (
    <Provisioning
      phase={account.status === "ERROR" ? "error" : transitional ? "working" : "ready"}
      liveStep={stepLabel}
      simulate={process.env.NXEON_SANDBOX === "1" && !stepLabel}
      service="hosting"
      hostname={account.primaryDomain}
      planName={account.planName}
      osName=""
      connectAddress={sftpHost ? `sftp://${account.username}@${sftpHost}` : null}
      error={account.error}
      dashboardHref={`/dashboard/hosting/${account.id}`}
      specs={[
        /* Real figures off the account view. Disk is the plan quota plus any
           extra bought at deploy, the same total the rest of the page shows. */
        { icon: "database", text: `${Math.round(account.diskQuotaMB / 1024) + account.extraDiskGB} GB storage` },
        { icon: "globe3", text: `${account.maxSites} site${account.maxSites === 1 ? "" : "s"}` },
        { icon: "envelope", text: account.planMailboxes < 0 ? "Unlimited mailboxes" : `${account.planMailboxes} mailboxes` },
      ]}
    />
  );

  return (
    <div>
      {overlay}
      {(transitional || installStepActive) && <AutoRefresh />}

      <div className="mb-6">
        <div className="flex flex-wrap items-center gap-3">
          <h1 className="page-title">{account.primaryDomain}</h1>
          <StatusDot status={account.status} />
          {account.sslActive && <Badge tone="green">HTTPS</Badge>}
        </div>
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <Badge tone="slate">{account.planName}</Badge>
          <Badge tone="slate">PHP {account.phpVersion}</Badge>
          <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">← All hosting</a>
        </div>
      </div>

      {transitional && (
        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
          Your account is being set up — this usually takes under a minute. This page refreshes automatically.
        </div>
      )}

      <HostingTabs account={account} initialTab={tab} initialPath={path} />
    </div>
  );
}

