72	/**
73	 * Pick the port forward that actually serves a game server's own port, not
74	 * just the first one on the record — a customer can add extra forwards
75	 * (RCON web UI, Dynmap, a Bedrock/Geyser port, ...) that must never be
76	 * mistaken for the game's real connect port. Falls back to the first forward
77	 * if none matches, so a server whose family isn't in GAME_PORT (or has no
78	 * exact-matching forward yet) still shows *something* rather than nothing.
79	 * Single shared helper so the provisioning-overlay connect string, the header
80	 * connect string, and the custom-domain DNS instructions can never drift from
81	 * each other the way three independent inline copies previously could.
82	 *
83	 * Keys on `joinPortFor`, NOT `GAME_PORT`. `GAME_PORT` is the health-CHECK map
84	 * and for eight families (rust, ark, projectzomboid, factorio, arkasa, soulmask,
85	 * squad, kf2) it deliberately names an RCON/query/admin port instead of the join
86	 * port — see its comment in lib/games.ts. Reading it here meant a Rust customer
87	 * was shown their RCON port, 28016, as the address to give their players. Found
88	 * live 2026-09-06 on a real fresh provision. The RCON forward still exists (the
89	 * provisioning health check runs through it), so this must select the join port
90	 * explicitly rather than rely on there being only one game forward.
91	 */
92	function gameForwardFor(server: {
93	  portForwards: { guestPort: number; publicPort: number }[];
94	  osTemplate: { family?: string | null };
95	  gamePlan?: { gameFamily?: string | null } | null;
96	}): { guestPort: number; publicPort: number } | undefined {
97	  const family = (server.gamePlan?.gameFamily ?? server.osTemplate.family) as GameFamily | undefined;
98	  const joinPort = family && GAME_PORT[family] ? joinPortFor(family).port : undefined;
99	  const checkPort = family ? GAME_PORT[family]?.port : undefined;
100	  return (
101	    server.portForwards.find((f) => f.guestPort === joinPort) ??
102	    // The join forward can be legitimately absent on a server provisioned before
103	    // it was ever allocated — fall back to the check port rather than showing
104	    // nothing, same spirit as the final fallback below.
105	    server.portForwards.find((f) => f.guestPort === checkPort) ??
106	    server.portForwards[0]
107	  );
108	}
109	
110	function fmtUptime(seconds: number): string {
111	  if (!seconds || seconds <= 0) return "—";
112	  const d = Math.floor(seconds / 86400);
113	  const h = Math.floor((seconds % 86400) / 3600);
114	  const m = Math.floor((seconds % 3600) / 60);
115	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
116	}
