127	export default async function ServerPage({
128	  params,
129	  searchParams,
130	}: {
131	  params: Promise<{ id: string }>;
132	  searchParams: Promise<{ tab?: string; purchase?: string }>;
133	}) {
134	  const [{ id }, { tab, purchase }] = await Promise.all([params, searchParams]);
135	  const user = await requireUser();
136	  const server = await db.server.findUnique({
137	    where: { id },
138	    include: {
139	      plan: true,
140	      osTemplate: true,
141	      project: true,
142	      portForwards: { orderBy: { publicPort: "asc" } },
143	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
144	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
145	      dedicatedIp: true,
146	      node: true,
147	      // Needed to price a renewal correctly: a game server bills its game plan's
148	      // flat price, not the base VPS plan's term price.
149	      gamePlan: true,
150	    },
151	  });
152	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
153	
154	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
155	  // display value through the decrypt fallback (legacy plaintext rows still work).
156	  const rootPassword = serverRootPassword(server);
157	
158	  const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct, ipMonthlyCentsLive] =
159	    await Promise.all([
160	      db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
161	      db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
162	      db.osTemplate.findMany({
163	        where: { active: true, category: "PLAIN_OS" },
164	        orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
165	      }),
166	      extraDiskPerGbCents(),
167	      backupPlusMonthlyCents(),
168	      // Live annual discount — feeds the "Renew now" quote below AND the resize
169	      // pickers, so an annual server's renewal/upgrade/downgrade all price against the
170	      // same rate it was sold at.
171	      annualDiscountPct(),
172	      // Fetched unconditionally now (not just `server.dedicatedIp ? … : 0`): the
173	      // "Add dedicated IP" card needs the live price to show a customer who does
174	      // NOT yet have one, same as extraDiskPriceCents above is fetched regardless
175	      // of whether this server currently holds any extra disk.
176	      dedicatedIpMonthlyCents(),
177	    ]);
178	
179	  // VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
180	  const owner =
181	    server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
182	  const renewTaxCtx = await taxContextForUser(owner);
183	
184	  // What "Renew now" will actually charge, priced through the SAME function the
185	  // action charges through, so the button cannot quote one figure and take
186	  // another. See lib/renewal-quote.ts for the incident.
187	  const renewQuote = renewalQuote(
188	    {
189	      termMonths: server.termMonths,
190	      extraDiskGB: server.extraDiskGB,
191	      plan: { name: server.plan.name, priceCents: server.plan.priceCents },
192	      // A game server is sold at its game plan's flat price, NOT the base VPS
193	      // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
194	      // a $4.99 product.
195	      gamePlan: server.gamePlan
196	        ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
197	        : null,
198	      dedicatedIp: server.dedicatedIp,
199	      backupTier: server.backupTier,
200	    },
201	    {
202	      ipMonthlyCents: server.dedicatedIp ? ipMonthlyCentsLive : 0,
203	      extraDiskPerGbCents: extraDiskPriceCents,
204	      backupPlusCents,
205	      annualDiscountPct: annualPct,
206	      // VAT/GST for the owner (Finding 1): the "Renews at $X" figure and the Renew
207	      // now quote are tax-inclusive, matching what renewNow charges.
208	      taxRatePercent: renewTaxCtx.ratePercent,
209	    },
210	  );
211	
212	  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
213	  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
214	  //
215	  // FIXED 2026-09-09: for a game server, "plan allowance" means the GAME
216	  // plan's disk, not the base VPS plan's — worker/index.ts's `provision()`
217	  // has used `server.gamePlan?.diskGB ?? server.plan.diskGB` since the
218	  // 2026-09-06 over-provisioning fix (a game plan is never LARGER than its
219	  // base VPS tier), but this page's own `totalDiskGB` was never updated to
220	  // match, so a game server's dashboard silently showed the bigger base-VPS
221	  // number here even though the VM itself was correctly provisioned at the
222	  // smaller, advertised size. Found live on a real Valheim server (30GB
223	  // advertised + actually provisioned, dashboard showed 50GB) — the exact
224	  // "advertised != displayed" trust problem the original fix existed to
225	  // prevent, just relocated to the display layer instead of provisioning.
226	  const baseDiskGB = server.gamePlan?.diskGB ?? server.plan.diskGB;
227	  const totalDiskGB = effectiveDiskGB(baseDiskGB, server.extraDiskGB);
228	
229	  const publicIp = server.node?.publicIp ?? process.env.PUBLIC_IP ?? "";
230	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
231	  const busy =
232	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
233	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
234	
235	  let live: LiveStats = null;
236	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
237	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
238	  let pveUnavailable = false;
239	
240	  if (server.vmid && steady) {
241	    // Read through THIS server's own node's Proxmox client — vmids can
242	    // collide across nodes, so the bare vmStatus/listSnapshots/listBackups
243	    // (always the primary node) would show a customer someone else's VM's
244	    // stats the moment their server lives on a different node. Falls back to
245	    // the primary-node singleton only for the legacy case of a server with
246	    // no `node` relation at all (pre-multi-node rows).
247	    const conn = server.node ? pveForNode(server.node) : null;
248	    // listBackupsOn's own default storage id ("backup") is the PRIMARY's own
249	    // vzdump storage name — a non-primary node's is its own `storageHdd`
250	    // (worker/index.ts and lib/actions-server-ops.ts already resolve it this
251	    // way). Omitting this here made every node-2+ server's Backups tab fail
252	    // with "hypervisor is briefly unavailable" — confirmed live 2026-09-08,
253	    // Proxmox 500s on GET /nodes/<node>/storage/backup/content because that
254	    // storage id doesn't exist there (node-2's is "vmdata-hdd").
255	    const backupStorage = server.node
256	      ? server.node.isPrimary
257	        ? "backup"
258	        : (server.node.storageHdd ?? "backup")
259	      : "backup";
260	    const results = await Promise.allSettled([
261	      conn ? conn.vmStatus(server.vmid) : vmStatus(server.vmid),
262	      conn ? listSnapshotsOn(conn, server.vmid) : listSnapshots(server.vmid),
263	      conn ? listBackupsOn(conn, server.vmid, backupStorage) : listBackups(server.vmid),
264	    ]);
265	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
266	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
267	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
268	    pveUnavailable = results.some((r) => r.status === "rejected");
269	  }
270	
271	  // Dedicated-IP servers connect straight to their own public IP on port 22; NAT
272	  // servers use the platform public IP + the forwarded SSH port. (A dedicated
273	  // server has sshPort=null, which previously fell through to "provisioning…".)
274	  const sshCommand = server.dedicatedIp
275	    ? `ssh root@${server.dedicatedIp.address}`
276	    : server.sshPort
277	      ? `ssh root@${publicIp} -p ${server.sshPort}`
278	      : null;
279	
280	  // Single-item terminal list for this server — connect string computed the
281	  // same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
282	  const terminalServers = [
283	    {
284	      id: server.id,
285	      hostname: server.hostname,
286	      connect: server.dedicatedIp
287	        ? `ssh root@${server.dedicatedIp.address}`
288	        : `ssh -p ${server.sshPort ?? 22} root@${publicIp || "YOUR_SERVER_IP"}`,
289	    },
290	  ];
291	
292	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
293	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
294	  const dedicated = !!server.dedicatedIp;
295	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
296	  const sftpPort = dedicated ? 22 : server.sshPort;
297	  /* A game server is one that was SOLD as a game server — `gamePlanId` — and
298	     its family is the game plan's, falling back to the OS template's.
299	     This used to test `osTemplate.family` alone, which is wrong whenever a game
300	     is installed on top of a plain OS image: `mc-survival` carries
301	     gamePlan.gameFamily="minecraft" on osTemplate.family="ubuntu", so it failed
302	     the test and rendered the VPS panel — no game console, no players, no mods,
303	     no game settings, for a Minecraft server. lib/game-config.ts's `familyFor`
304	     has always used this precedence; the page now matches it. */
305	  const isGameServer =
306	    server.gamePlanId !== null || GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
307	
308	  // Post-payment "setting up / it's live" interstitial. Connect string mirrors
309	  // the game-branch's own `connect` computation below via the shared
310	  // gameForwardFor() helper, so the two can never drift from each other.
311	  const overlayForward = isGameServer ? gameForwardFor(server) : undefined;
312	  const overlayConnect = isGameServer
313	    ? server.dedicatedIp
314	      ? `${server.dedicatedIp.address}${overlayForward ? `:${overlayForward.guestPort}` : ""}`
315	      : overlayForward
316	        ? `${publicIp}:${overlayForward.publicPort}`
317	        : publicIp || null
318	    : sshCommand;
319	  // Real (not cosmetic) step label when the worker has recorded one for this
320	  // server's CURRENT provisioning run — see lib/provisioning-step.ts. Null while
321	  // transitional but no checkpoint reached yet (or in SANDBOX, which completes
322	  // before any step is ever written) simply falls back to the overlay's existing
323	  // cosmetic cycling text.
324	  const liveStep = transitional ? await serverProvisioningStep(server.id) : null;
325	  /* The Nexion provisioning screen. It replaces <ProvisioningOverlay/> for the
326	     three states it covers — building, live, failed — and is driven by the SAME
327	     real signals the old one used: `server.status` and `serverProvisioningStep`.
328	     The design sandbox animated this on a timer; nothing here advances unless
329	     the worker actually reported a step.
330	
331	     This is the destination `payAndDeploy` redirects to, so it is the screen a
332	     customer really sees after ordering — the wizard's own step 5 is never
333	     reached on that path. */
334	  const overlay = transitional || purchase === "1" || server.status === "ERROR" ? (
335	    <Provisioning
336	      phase={server.status === "ERROR" ? "error" : transitional ? "working" : "ready"}
337	      liveStep={liveStep}
338	      /* Sandbox only: no hypervisor here means the worker never reports a step,
339	         so the stage list would sit inert forever and the screen could not be
340	         judged. Never true in production — NXEON_SANDBOX is not set there. */
341	      simulate={process.env.NXEON_SANDBOX === "1" && !liveStep}
342	      hostname={server.hostname}
343	      planName={isGameServer ? server.gamePlan?.name ?? server.plan.name : server.plan.name}
344	      osName={server.osTemplate.name}
345	      connectAddress={overlayConnect}
346	      error={server.provisionError}
347	      dashboardHref={`/dashboard/servers/${server.id}`}
