import { GAME_PORT, type GameFamily } from "@/lib/games";

/** What a connect address IS, so a row can label it rather than guess. */
export type AddressLabel = "IP address" | "Connect" | "Website";

/**
 * The address a customer can actually reach a server on.
 *
 * Deliberately NOT `Server.ipAddress`: that column holds the internal
 * 10.20.x.x address behind the host's NAT, which is unreachable from outside
 * and would be worse than showing nothing. This is the same derivation the
 * "your server is ready" email uses (lib/server-deployed-email.ts) — a
 * dedicated IP if the server has one, otherwise the NODE's public IP with the
 * forwarded port — so the dashboard and the email can never disagree about
 * where to connect.
 */
export function connectAddress(s: {
  gamePlanId: string | null;
  subdomain: string | null;
  sshPort: number | null;
  dedicatedIp: { address: string } | null;
  portForwards: { publicPort: number; guestPort: number }[];
  node: { publicIp: string } | null;
  osTemplate: { family: string } | null;
  gamePlan: { gameFamily: string } | null;
}, gameBase: string): { address: string | null; addressLabel: AddressLabel | null } {
  const host = s.dedicatedIp?.address ?? s.node?.publicIp ?? null;

  if (s.gamePlanId !== null) {
    // A play subdomain is the address the customer was actually given, so it
    // wins over the raw host:port even when both exist.
    if (s.subdomain) return { address: `${s.subdomain}.${gameBase}`, addressLabel: "Connect" };

    const family = (s.gamePlan?.gameFamily ?? s.osTemplate?.family ?? "") as GameFamily;
    const gamePort = GAME_PORT[family];
    if (gamePort && host) {
      // A dedicated IP exposes the game port directly; a shared node exposes
      // whatever public port the forward was allocated.
      const port = s.dedicatedIp
        ? gamePort.port
        : s.portForwards.find((f) => f.guestPort === gamePort.port)?.publicPort ?? null;
      if (port) return { address: `${host}:${port}`, addressLabel: "Connect" };
    }
    return host ? { address: host, addressLabel: "IP address" } : { address: null, addressLabel: null };
  }

  if (!host) return { address: null, addressLabel: null };
  // A dedicated IP is reachable on the standard SSH port; a shared node needs
  // the forwarded one.
  if (s.dedicatedIp) return { address: host, addressLabel: "IP address" };
  return { address: s.sshPort ? `${host}:${s.sshPort}` : host, addressLabel: "IP address" };
}
