/**
 * How a plan is written out in one line.
 *
 * Shared because three screens print it — the My Services cards, the migration
 * destination picker, and this module's own callers — and the game one has a
 * trap in it that each would otherwise fall into separately.
 */

/**
 * A game plan is named for the customer's benefit — "Minecraft — 2 GB / 10
 * slots" — so printing it next to the game name and the slot count again gives
 * "Minecraft · Minecraft — 2 GB / 10 slots • 10 slots". Strip the parts the row
 * already says elsewhere and keep only what the plan adds.
 */
export function gamePlanSpecs(planName: string | undefined, gameName: string | null, slots: number | null | undefined): string | null {
  if (!planName) return slots ? `${slots} slots` : null;
  let out = planName.trim();
  if (gameName && out.toLowerCase().startsWith(gameName.toLowerCase())) {
    out = out.slice(gameName.length).replace(/^\s*[—–-]\s*/, "").trim();
  }
  if (out) return out;
  return slots ? `${slots} slots` : null;
}

export function specLine(cpu: number, ramMB: number, diskGB: number, tier?: string): string {
  const ram = ramMB >= 1024 ? `${Math.round(ramMB / 1024)} GB RAM` : `${ramMB} MB RAM`;
  return `${cpu} vCPU • ${ram} • ${diskGB} GB ${tier === "hdd" ? "HDD" : "NVMe"}`;
}
