type Status = {
  planName?: string;
  primaryDomain?: string;
  includedMailboxes?: number;
  hasSubscription?: boolean;
  subscriptionId?: string;
  verified?: boolean;
  error?: string;
};

/**
 * Bundled hosting email. Reuses the audited /dashboard/email UI for the actual
 * mailbox management + DNS verification — this tab only kicks off the
 * complimentary subscription (setupHostingEmail) and then links across. It never
 * lists or provisions mailboxes itself.
 */
export function EmailTab({ account }: { account: HostingAccountView }) {
  const [status, setStatus] = useState<Status | null>(null);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  function refresh() {
    getHostingEmailStatus(account.id)
      .then((s) => setStatus(s))
      .catch(() => setStatus({ error: "Couldn’t load email status." }));
  }

  useEffect(() => {
    refresh();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [account.id]);

  async function setup() {
    setBusy(true);
    setErr(null);
