=== usage sweep ===
export async function hostingUsageSweep(): Promise<void> {
  if (SANDBOX || !ENABLED) return;
  const accts = await db.hostingAccount.findMany({ where: { status: "ACTIVE" }, include: { node: true }, take: 50 });
  for (const a of accts) {
    try {
      if (!isValidUnixUsername(a.username)) continue;
      const conn = await connectNode(a.node);
      try {
        const du = await exec(conn, `du -sm /home/${a.username} 2>/dev/null | cut -f1`, 60_000);
        const inodes = await exec(conn, `find /home/${a.username} -xdev 2>/dev/null | wc -l`, 60_000);
        const diskUsedMB = parseInt(du.out.trim(), 10);
        const inodesUsed = parseInt(inodes.out.trim(), 10);
        await db.hostingAccount.update({
          where: { id: a.id },
          data: {
            diskUsedMB: Number.isFinite(diskUsedMB) ? diskUsedMB : null,
            inodesUsed: Number.isFinite(inodesUsed) ? inodesUsed : null,
            usageAt: new Date(),
          },
        });
      } finally {
        try { conn.end(); } catch { /* */ }
      }
    } catch (e) {
      console.error(`[hosting] usage sweep ${a.id} failed`, e);
    }
  }
}

